def log_text(text: str, language: str = 'en') -> str:
    if language == 'fr':
        return text
    if text in LOG_TRANSLATIONS:
        return LOG_TRANSLATIONS[text]
    for pattern, replacement in LOG_PATTERNS:
        if re.match(pattern, text):
            return re.sub(pattern, replacement, text)
    return text
